/**
 * Softmato's letterhead (`marketing/agreement/source/letterhead.pdf`), as base64.
 *
 * A module rather than a file read from disk: route bundles carry only what is
 * imported, and a runtime `readFile` would need its own tracing entry per route
 * (`next.config.ts`), which silently 500s when it falls behind. Imported
 * lazily by the agreement renderer, so only a render pays for parsing it.
 * Regenerate from the PDF if the letterhead changes.
 */
export const AGREEMENT_LETTERHEAD_BASE64 =
  "";
